-- 0019_seed_pdf_catalog_products.sql
-- Products + variants from the Qeelasee OEM lash price list and the Fadvan catalog PDFs.
-- Run AFTER 0018 in the Supabase SQL editor. Safe to re-run (products match on slug; costs and options refresh).
--
--   * Qeelasee prices are supplier USD per tray (OEM list). They are stored as the private cost (product_costs.cost_usd)
--     and the storefront prices are set with the pricing formula in Site Settings (price_mode = 'formula').
--   * Fadvan has no prices in its catalog: those products are inserted with price 0 and no cost, as drafts.
--   * Variants (Thickness / Curl / Length ...) go in products.options with price_delta 0 (same price for every choice).
--   * Everything lands as DRAFT. Review, add photos, then activate (see the end of this file).

on conflict (slug) do nothing;

on conflict do nothing;

create temp table _import (slug text, sku text, name text, description text, supplier text, category text, cost_usd numeric, options jsonb, price_mode text, status text, badge text, sort int) on commit drop;

select i.slug, i.sku, i.name, i.description,
       (select id from public.categories where slug = i.category),
       (select id from public.suppliers where lower(name) = lower(i.supplier)),
       i.options, i.price_mode, i.status, 10, i.sort, 0, 0
from _import i
on conflict (slug) do update
  set name = excluded.name, description = excluded.description, options = excluded.options,
      category_id = excluded.category_id, supplier_id = excluded.supplier_id, price_mode = excluded.price_mode;

select p.id, i.cost_usd from _import i join public.products p on p.slug = i.slug where i.cost_usd is not null
on conflict (product_id) do update set cost_usd = excluded.cost_usd;

-- Apply the pricing formula (Site Settings -> Pricing formula) to the imported priced products.
update public.products p
   set now_price = f.wholesale, retail_price = f.retail, market_price = f.market
  from _import i
  join public.product_costs c on c.product_id = (select id from public.products where slug = i.slug)
  cross join lateral public.formula_prices(c.cost_usd) f
 where p.slug = i.slug and i.cost_usd is not null;

-- When reviewed, publish the priced Qeelasee products:
--   update public.products set status = 'active' where sku like 'QL-%';
-- Fadvan products stay draft until you give them prices in Admin -> Products.
